def bis(f, lo, hi, n=200):
    flo = f(lo)
    for _ in range(n):
        m = (lo + hi) / 2
        fm = f(m)
        if (flo <= 0) == (fm <= 0):
            lo, flo = m, fm
        else:
            hi = m
    return (lo + hi) / 2

def skill():
    b = next(k for k in range(1, 30) if 2**k - k == 5)
    a = 2**b
    area = Rational(1, 2) * abs(a*a - b*b)
    return area.p + area.q

def _u(a):
    y0 = math.log2(a)
    return bis(lambda x: 2**x - (y0 - (x - a)), -60, 60)

def standard():
    g = lambda a: math.sqrt((_u(a) - a)**2 + (2**_u(a) - math.log2(a))**2) - 5*math.sqrt(2)
    a = bis(g, 2, 100)
    u = _u(a)
    assert abs((a + u)/2 - (math.log2(a) + 2**u)/2) < 1e-6
    area = abs(a*(2**u) - u*math.log2(a)) / 2
    fr = Fraction(area).limit_denominator(1000)
    return fr.numerator + fr.denominator

def unique():
    return [standard()]
